# Autotune selects small XBLOCK (e.g. 32 threads)
@triton.autotune(
    configs=[Config({'XBLOCK': 16}, num_warps=1), ..., Config({'XBLOCK': 128}, num_warps=4)],
    key=['xnumel'],
)
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.arange(0, XBLOCK)[:]
    ...
# Autotuner picks XBLOCK=32 -> block_size=32, achieved_occupancy=1.56%
grid = (triton.cdiv(xnumel, 128),)  # fixed grid ignores autotuner XBLOCK
kernel[grid](args, xnumel=2304)

